<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import NodeMap from'./NodeMap.vue';import{getPlannerObjects,listLcps,listNaps,listOdfs,type PlannerData}from'./api';import type{NetworkNode,NodeType,TopologyLink}from'./contracts';
type Tab='nodes'|'links';const tab=ref<Tab>('nodes'),nodeType=ref<NodeType>('odf'),search=ref(''),loading=ref(false),error=ref(''),notice=ref(''),odfs=ref<NetworkNode[]>([]),lcps=ref<NetworkNode[]>([]),naps=ref<NetworkNode[]>([]),links=ref<TopologyLink[]>([]),detailOpen=ref(false),selected=ref<NetworkNode|null>(null);const allNodes=computed(()=>nodeType.value==='odf'?odfs.value:nodeType.value==='lcp'?lcps.value:naps.value);const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return allNodes.value.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));});const filteredLinks=computed(()=>{const q=search.value.trim().toLowerCase();return links.value.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));});function name(r:NetworkNode){return r.odf_name||r.lcp_name||r.nap_name||r.name||nodeType.value.toUpperCase()+' #'+r.id;}function code(r:NetworkNode){return r.odf_code||r.lcp_code||r.nap_code||r.code||'#'+r.id;}function ports(r:NetworkNode){return r.total_ports??r.splitter_ports??0;}function tone(v?:string):'success'|'danger'|'warning'|'neutral'{const s=String(v||'').toUpperCase();return s==='ACTIVE'?'success':s==='FAULTY'?'danger':s==='MAINTENANCE'?'warning':'neutral';}function legacyInventory(p:PlannerData,o:NetworkNode[]):TopologyLink[]{const nodes=(p.nodes||p.planner_nodes||[])as Record<string,any>[],raw=(p.links||[])as Record<string,any>[],rows:TopologyLink[]=[],seen=new Set<string>();const push=(k:string,r:TopologyLink)=>{if(!seen.has(k)){seen.add(k);rows.push(r);}};o.forEach(d=>{const olt=Number(d.olt_id||0);if(!olt)return;const source=String(d.olt_name||'OLT #'+olt),target=String(d.odf_name||d.name||'ODF #'+d.id),port=String(d.olt_port_path||d.olt_port_label||d.olt_port_id||'');push('FEEDER:'+olt+':'+d.id,{id:Number(d.id),link_type:'FEEDER',identification:source+(port?' ['+port+']':'')+' → '+target+' [Port '+String(d.input_port_number||1)+']',source_name:source,target_name:target});});raw.forEach(l=>{const s=nodes.find(n=>Number(n.id)===Number(l.source_node_id)),t=nodes.find(n=>Number(n.id)===Number(l.target_node_id));if(!s||!t)return;const sn=String(s.node_name||s.name||s.odf_name||s.lcp_name||s.nap_name||String(s.node_type||'NODE')+' #'+String(s.reference_id||s.id)),tn=String(t.node_name||t.name||t.odf_name||t.lcp_name||t.nap_name||String(t.node_type||'NODE')+' #'+String(t.reference_id||t.id)),sp=String(l.source_port_label||l.source_port_id||''),tp=String(l.target_port_label||l.target_port_id||''),kind=String(l.link_type||'DISTRIBUTION').toUpperCase(),key=kind+':'+l.source_node_id+':'+l.target_node_id+':'+sp+':'+tp;push(key,{id:Number(l.id||0),link_type:kind,identification:sn+(sp?' ['+sp+']':'')+' → '+tn+(tp?' ['+tp+']':''),source_name:sn,target_name:tn});});return rows;}async function load(show=false){loading.value=true;error.value='';notice.value='';try{const[o,l,n,p]=await Promise.all([listOdfs(),listLcps(),listNaps(),getPlannerObjects()]);odfs.value=o||[];lcps.value=l||[];naps.value=n||[];links.value=legacyInventory(p||{},odfs.value);if(show)notice.value='NAP infrastructure refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load NAP infrastructure.';}finally{loading.value=false;}}function show(r:NetworkNode){selected.value=r;detailOpen.value=true;}function mapUrl(r:NetworkNode){const a=Number(r.latitude),o=Number(r.longitude);return Number.isFinite(a)&&Number.isFinite(o)?'https://www.openstreetmap.org/export/embed.html?bbox='+(o-.003)+'%2C'+(a-.003)+'%2C'+(o+.003)+'%2C'+(a+.003)+'&layer=mapnik&marker='+a+'%2C'+o:'';}onMounted(()=>void load());
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="FTTH infrastructure" title="NAP Management" description="Review ODF, LCP, NAP, and physical network-link infrastructure in consistent tabular workspaces."><template #actions><a href="/nap-management?legacy_ui=1&tab=planner" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-4 text-sm font-semibold text-[var(--nx-text)] no-underline">Open Visual Planner</a><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="x in [['ODF Nodes',odfs.length],['LCP Boxes',lcps.length],['NAP Boxes',naps.length],['Topology Links',links.length]]" :key="String(x[0])"><p class="text-xs font-bold uppercase text-[var(--nx-text-muted)]">{{x[0]}}</p><p class="mt-2 text-2xl font-bold">{{x[1]}}</p></NxCard></section><NxToolbar><div class="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div role="tablist" aria-label="NAP views" class="flex gap-2"><button v-for="x in [['nodes','Nodes'],['links','Links']]" :key="x[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="tab===x[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab=x[0] as Tab">{{x[1]}}</button></div><div v-if="tab==='nodes'" role="tablist" aria-label="Node types" class="flex gap-2"><button v-for="k in ['odf','lcp','nap']" :key="k" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="nodeType===k?'bg-slate-700 text-white':'bg-[var(--nx-surface-muted)]'" @click="nodeType=k as NodeType">{{k.toUpperCase()}}</button></div><input v-model="search" type="search" placeholder="Search infrastructure…" class="min-h-11 w-full rounded-md bg-[var(--nx-surface-muted)] px-4 lg:max-w-sm"></div></NxToolbar>
<NxTableShell v-if="tab==='nodes'" min-width="1000px"><thead><tr><th class="px-4 py-3">Node</th><th class="px-4 py-3">Parent / Uplink</th><th class="px-4 py-3">Ports</th><th class="px-4 py-3">Location</th><th class="px-4 py-3">Coordinates</th><th class="px-4 py-3">Status</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="7" class="p-12 text-center">No records found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3"><b>{{name(r)}}</b><small class="block text-[var(--nx-text-muted)]">{{code(r)}}</small></td><td class="px-4 py-3">{{r.parent_name||r.olt_name||r.lcp_name||'—'}}</td><td class="px-4 py-3">{{r.used_ports??0}} / {{ports(r)}}</td><td class="px-4 py-3">{{r.location||'—'}}</td><td class="px-4 py-3">{{r.latitude&&r.longitude?r.latitude+', '+r.longitude:'Not pinned'}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{r.status||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3 text-right"><NxButton variant="secondary" @click="show(r)">View</NxButton></td></tr></tbody></NxTableShell>
<NxTableShell v-else min-width="850px"><thead><tr><th class="px-4 py-3">Identification</th><th class="px-4 py-3">Source</th><th class="px-4 py-3">Target</th><th class="px-4 py-3">Type</th></tr></thead><tbody><tr v-if="!filteredLinks.length"><td colspan="4" class="p-12 text-center">No topology links found.</td></tr><tr v-for="l in filteredLinks" :key="l.id"><td class="px-4 py-3">{{l.identification||'#'+l.id}}</td><td class="px-4 py-3">{{l.source_name||l.source_type||'—'}}</td><td class="px-4 py-3">{{l.target_name||l.target_type||'—'}}</td><td class="px-4 py-3">{{l.link_type||'PHYSICAL'}}</td></tr></tbody></NxTableShell>
<NxModal :open="detailOpen" :title="selected?name(selected):'Node Details'" description="Operational identity, uplink, capacity, status, and location." max-width="60rem" @close="detailOpen=false"><div class="grid gap-5 p-6 lg:grid-cols-2"><dl class="grid content-start gap-3 sm:grid-cols-2"><div v-for="x in Object.entries(selected||{}).filter(([k,v])=>['odf_name','lcp_name','nap_name','box_name','box_code','location','address','parent_name','status','total_ports','splitter_ports','used_ports','free_ports','feed_mode','remarks','latitude','longitude','created_at'].includes(k)&&v!==null&&v!=='')" :key="x[0]" class="rounded-md bg-[var(--nx-surface-muted)] p-3"><dt class="text-xs font-bold uppercase text-[var(--nx-text-muted)]">{{x[0].replaceAll('_',' ')}}</dt><dd class="mt-1 break-all text-sm">{{x[1]??'—'}}</dd></div></dl><NodeMap v-if="selected&&mapUrl(selected)" :latitude="selected.latitude as string|number" :longitude="selected.longitude as string|number" :label="name(selected)"/><NxAlert v-else tone="warning">This node has no valid coordinates.</NxAlert></div><template #footer><NxButton variant="secondary" @click="detailOpen=false">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="nap"]){max-width:100%;overflow-x:hidden}</style>
